"""
Generates info log in Test Execution Errors section in log.html
"""

from robot.output.loggerhelper import Message
from robot.output.logger import LOGGER
from robot.reporting.jsmodelbuilders import MessageBuilder


def hack_build_function():
    hacked_build_function = MessageBuilder.build

    def new_build_function(self, msg):
        if msg.level == "INFO":
            self._context.create_link_target(msg)
        return hacked_build_function(self, msg)

    MessageBuilder.build = new_build_function


def log_message_with_hyperlink(message, **kwargs):
    """
    :param message: log message
    :param kwargs: additional kwargs to robot.output.loggerhelper.Message
    """
    msg_obj = Message(message, **kwargs)
    xml_logger = LOGGER._xml_logger.logger
    xml_logger.log_message(msg_obj)
    xml_logger._errors.append(msg_obj)


hack_build_function()
